pub fn glyph(name: &str) -> Option<(u32, &'static str)> {
    let index = GLYPH_NAMES.binary_search(&name).ok()?;
    let mut chars = GLYPH_UNICODE[index].chars();
    let first = chars.next()?;
    if chars.next().is_some() {
        return None;
    }
    Some((first as u32, GLYPH_NAMES[index]))
}

pub fn glyph_text(name: &str) -> Option<&'static str> {
    let index = GLYPH_NAMES.binary_search(&name).ok()?;
    Some(GLYPH_UNICODE[index])
}

