pub struct ByteEncoding {
    pub unicode: &'static [u32; 256],
    pub names: &'static [&'static str; 256],
}

pub fn encoding(name: &str) -> Option<ByteEncoding> {
    Some(match name {
        "WinAnsiEncoding" => ByteEncoding {
            unicode: &WINANSIENCODING_UNICODE,
            names: &WINANSIENCODING_NAMES,
        },
        "MacRomanEncoding" => ByteEncoding {
            unicode: &MACROMANENCODING_UNICODE,
            names: &MACROMANENCODING_NAMES,
        },
        "StandardEncoding" => ByteEncoding {
            unicode: &STANDARDENCODING_UNICODE,
            names: &STANDARDENCODING_NAMES,
        },
        "SymbolEncoding" => ByteEncoding {
            unicode: &SYMBOLENCODING_UNICODE,
            names: &SYMBOLENCODING_NAMES,
        },
        "ZapfDingbatsEncoding" => ByteEncoding {
            unicode: &ZAPFDINGBATSENCODING_UNICODE,
            names: &ZAPFDINGBATSENCODING_NAMES,
        },
        "PDFDocEncoding" => ByteEncoding {
            unicode: &PDFDOCENCODING_UNICODE,
            names: &PDFDOCENCODING_NAMES,
        },
        "MacExpertEncoding" => ByteEncoding {
            unicode: &MACEXPERTENCODING_UNICODE,
            names: &MACEXPERTENCODING_NAMES,
        },
        _ => return None,
    })
}

pub struct FontMetric {
    pub name: &'static str,
    pub ascent: i16,
    pub descent: i16,
    pub glyphs: &'static [&'static str],
    pub widths: &'static [u16],
}

